def compute(vars):
    net_sales_2018 = vars["v2"]
    net_sales_2017 = vars["v1"]
    value = (net_sales_2018 + net_sales_2017) / 2
    return {
        "value": value,
        "trace": {
            "net_sales_2018": net_sales_2018,
            "net_sales_2017": net_sales_2017,
            "average_net_sales": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
